; Left-right movement table
;
; Used by the routine at MOVEWILLY2. The entries in this table are used to map the
; existing value (V) of Willy's direction and movement flags at DMFLAGS to a
; new value (V'), depending on the direction Willy is facing and how he is
; moving or being moved (by 'left' and 'right' keypresses and joystick input,
; or by a conveyor).
; .
; One of the first four entries is used when Willy is not moving.
; --------------------------------------------------------------------
LRMOVEMENT:
        DEFB  0                      ; V=0 (facing right, no movement) + no movement: V'=0 (no      [33800]
                                     ;   change)
        DEFB  1                      ; V=1 (facing left, no movement) + no movement: V'=1 (no      [33801]
                                     ;   change)
        DEFB  0                      ; V=2 (facing right, moving) + no movement: V'=0 (facing      [33802]
                                     ;   right, no movement) (i.e. stop)
        DEFB  1                      ; V=3 (facing left, moving) + no movement: V'=1 (facing      [33803]
                                     ;   left, no movement) (i.e. stop)
; --------------------------------------------------------------------
; One of the next four entries is used when Willy is moving left.
; --------------------------------------------------------------------
        DEFB  1                      ; V=0 (facing right, no movement) + move left: V'=1      [33804]
                                     ;   (facing left, no movement) (i.e. turn around)
        DEFB  3                      ; V=1 (facing left, no movement) + move left: V'=3 (facing      [33805]
                                     ;   left, moving)
        DEFB  1                      ; V=2 (facing right, moving) + move left: V'=1 (facing      [33806]
                                     ;   left, no movement) (i.e. turn around)
        DEFB  3                      ; V=3 (facing left, moving) + move left: V'=3 (no change)      [33807]
; --------------------------------------------------------------------
; One of the next four entries is used when Willy is moving right.
; --------------------------------------------------------------------
        DEFB  2                      ; V=0 (facing right, no movement) + move right: V'=2      [33808]
                                     ;   (facing right, moving)
        DEFB  0                      ; V=1 (facing left, no movement) + move right: V'=0      [33809]
                                     ;   (facing right, no movement) (i.e. turn around)
        DEFB  2                      ; V=2 (facing right, moving) + move right: V'=2 (no      [33810]
                                     ;   change)
        DEFB  0                      ; V=3 (facing left, moving) + move right: V'=0 (facing      [33811]
                                     ;   right, no movement) (i.e. turn around)
; --------------------------------------------------------------------
; One of the final four entries is used when Willy is being pulled both left
; and right; each entry leaves the flags at DMFLAGS unchanged (so Willy carries
; on moving in the direction he's already moving, or remains stationary).
; --------------------------------------------------------------------
        DEFB  0                      ; V=V'=0 (facing right, no movement)      [33812]
        DEFB  1                      ; V=V'=1 (facing left, no movement)      [33813]
        DEFB  2                      ; V=V'=2 (facing right, moving)      [33814]
        DEFB  3                      ; V=V'=3 (facing left, moving)      [33815]
; --------------------------------------------------------------------
; 'AIR'
;
; Used by the routine at STARTGAME.
; --------------------------------------------------------------------
MESSAIR:
        DEFM  "AIR"                  ;                              [33816]
; --------------------------------------------------------------------
; Unused
; --------------------------------------------------------------------
        DEFM  "0000"                 ;                              [33819]
; --------------------------------------------------------------------
; High score
;
; Used by the routine at LOOP and updated by the routine at ENDGAM.
; --------------------------------------------------------------------
HGHSCOR:
        DEFM  "000000"               ;                              [33823]
; --------------------------------------------------------------------
; Score
;
; Initialised by the routine at STARTGAME, and used by the routines at LOOP,
; ENDGAM, NXSHEET and INCSCORE.
; --------------------------------------------------------------------
SCORE:
        DEFM  "0000"                 ; Overflow digits (these may be updated, but are never      [33829]
                                     ;   printed)
SCORBUF:
        DEFM  "000000"               ;                              [33833]
; --------------------------------------------------------------------
; 'High Score 000000Score 000000'
;
; Used by the routine at STARTGAME.
; --------------------------------------------------------------------
MESSHSSC:
        DEFM  "High Score 000000   Score 000000" ;                              [33839]
; --------------------------------------------------------------------
; 'Game'
;
; Used by the routine at ENDGAM.
; --------------------------------------------------------------------
MESSG:
        DEFM  "Game"                 ;                              [33871]
; --------------------------------------------------------------------
; 'Over'
;
; Used by the routine at ENDGAM.
; --------------------------------------------------------------------
MESSO:
        DEFM  "Over"                 ;                              [33875]
; --------------------------------------------------------------------
; Lives remaining
;
; Initialised to 2 by the routine at START, and used and updated by the
; routines at LOOP and INCSCORE.
; --------------------------------------------------------------------
NOMEN:
        DEFB  0                      ;                              [33879]
; --------------------------------------------------------------------
; Screen flash counter
;
; Initialised by the routine at START, and used by the routines at LOOP
; and INCSCORE.
; --------------------------------------------------------------------
FLASH:
        DEFB  0                      ;                              [33880]
; --------------------------------------------------------------------
; Kempston joystick indicator
;
; Initialised by the routine at START, and used by the routines at LOOP,
; MOVEWILLY2 and CHECKENTER. Holds 1 if a joystick is present, 0 otherwise.
; --------------------------------------------------------------------
KEMP:
        DEFB  0                      ;                              [33881]
; --------------------------------------------------------------------
; Game mode indicator
;
; Initialised by the routine at START, and used by the routines at STARTGAME,
; LOOP and NXSHEET. Holds #b0 when a game is in progress, or a value from
; #b1 to #b64 when in demo mode.
; --------------------------------------------------------------------
DEMO:
        DEFB  0                      ;                              [33882]
; --------------------------------------------------------------------
; In-game music note index
;
; Initialised by the routine at START, and used and updated by the routine at
; LOOP.
; --------------------------------------------------------------------
NOTEINDEX:
        DEFB  0                      ;                              [33883]
; --------------------------------------------------------------------
; Music flags
;
; The keypress flag in bit 0 is initialised by the routine at START; bits 0
; and 1 are checked and updated by the routine at LOOP.
; .
;
; =h Bit(s) | =h Meaning
; 0 | Keypress flag (set=H-ENTER being pressed, reset=no key pressed)
; 1 | In-game music flag (set=music off, reset=music on)
; 2-7 | Unused
; TABLE#
; --------------------------------------------------------------------
MUSICFLAGS:
        DEFB  0                      ;                              [33884]
; --------------------------------------------------------------------
; 6031769 key counter
;
; Used by the routines at LOOP and NXSHEET.
; --------------------------------------------------------------------
CHEAT:
        DEFB  0                      ;                              [33885]
; --------------------------------------------------------------------
; 6031769
;
; Used by the routine at LOOP. In each pair of bytes here, bits 0-4 of the
; first byte correspond to keys 1-2-3-4-5, and bits 0-4 of the second byte
; correspond to keys 0-9-8-7-6; among those bits, a zero indicates a key being
; pressed.
; --------------------------------------------------------------------
        DEFB  %00011111,%00011111    ; (no keys pressed)      [33886]
CHEATDT:
        DEFB  %00011111,%00001111    ; 6      [33888]
        DEFB  %00011111,%00011110    ; 0      [33890]
        DEFB  %00011011,%00011111    ; 3      [33892]
        DEFB  %00011110,%00011111    ; 1      [33894]
        DEFB  %00011111,%00010111    ; 7      [33896]
        DEFB  %00011111,%00001111    ; 6      [33898]
        DEFB  %00011111,%00011101    ; 9      [33900]
; --------------------------------------------------------------------
; Title screen tune data (The Blue Danube)
;
; Used by the routine at PLAYTUNE. The tune data is organised into 95 groups of
; three bytes each, one group for each note in the tune. The first byte in each
; group determines the duration of the note, and the second and third bytes
; determine the frequency (and also the piano keys that light up).
; --------------------------------------------------------------------
THEMETUNE:
        DEFB  80,128,129             ;                              [33902]
        DEFB  80,102,103             ;                              [33905]
        DEFB  80,86,87               ;                              [33908]
        DEFB  50,86,87               ;                              [33911]
        DEFB  50,171,203             ;                              [33914]
        DEFB  50,43,51               ;                              [33917]
        DEFB  50,43,51               ;                              [33920]
        DEFB  50,171,203             ;                              [33923]
        DEFB  50,51,64               ;                              [33926]
        DEFB  50,51,64               ;                              [33929]
        DEFB  50,171,203             ;                              [33932]
        DEFB  50,128,129             ;                              [33935]
        DEFB  50,128,129             ;                              [33938]
        DEFB  50,102,103             ;                              [33941]
        DEFB  50,86,87               ;                              [33944]
        DEFB  50,96,86               ;                              [33947]
        DEFB  50,171,192             ;                              [33950]
        DEFB  50,43,48               ;                              [33953]
        DEFB  50,43,48               ;                              [33956]
        DEFB  50,171,192             ;                              [33959]
        DEFB  50,48,68               ;                              [33962]
        DEFB  50,48,68               ;                              [33965]
        DEFB  50,171,192             ;                              [33968]
        DEFB  50,136,137             ;                              [33971]
        DEFB  50,136,137             ;                              [33974]
        DEFB  50,114,115             ;                              [33977]
        DEFB  50,76,77               ;                              [33980]
        DEFB  50,76,77               ;                              [33983]
        DEFB  50,171,192             ;                              [33986]
        DEFB  50,38,48               ;                              [33989]
        DEFB  50,38,48               ;                              [33992]
        DEFB  50,171,192             ;                              [33995]
        DEFB  50,48,68               ;                              [33998]
        DEFB  50,48,68               ;                              [34001]
        DEFB  50,171,192             ;                              [34004]
        DEFB  50,136,137             ;                              [34007]
        DEFB  50,136,137             ;                              [34010]
        DEFB  50,114,115             ;                              [34013]
        DEFB  50,76,77               ;                              [34016]
        DEFB  50,76,77               ;                              [34019]
        DEFB  50,171,203             ;                              [34022]
        DEFB  50,38,51               ;                              [34025]
        DEFB  50,38,51               ;                              [34028]
        DEFB  50,171,203             ;                              [34031]
        DEFB  50,51,64               ;                              [34034]
        DEFB  50,51,64               ;                              [34037]
        DEFB  50,171,203             ;                              [34040]
        DEFB  50,128,129             ;                              [34043]
        DEFB  50,128,129             ;                              [34046]
        DEFB  50,102,103             ;                              [34049]
        DEFB  50,86,87               ;                              [34052]
        DEFB  50,64,65               ;                              [34055]
        DEFB  50,128,171             ;                              [34058]
        DEFB  50,32,43               ;                              [34061]
        DEFB  50,32,43               ;                              [34064]
        DEFB  50,128,171             ;                              [34067]
        DEFB  50,43,51               ;                              [34070]
        DEFB  50,43,51               ;                              [34073]
        DEFB  50,128,171             ;                              [34076]
        DEFB  50,128,129             ;                              [34079]
        DEFB  50,128,129             ;                              [34082]
        DEFB  50,102,103             ;                              [34085]
        DEFB  50,86,87               ;                              [34088]
        DEFB  50,64,65               ;                              [34091]
        DEFB  50,128,152             ;                              [34094]
        DEFB  50,32,38               ;                              [34097]
        DEFB  50,32,38               ;                              [34100]
        DEFB  50,128,152             ;                              [34103]
