        DEFB  50,38,48               ;                              [34109]
        DEFB  50,0,0                 ;                              [34112]
        DEFB  50,114,115             ;                              [34115]
        DEFB  50,114,115             ;                              [34118]
        DEFB  50,96,97               ;                              [34121]
        DEFB  50,76,77               ;                              [34124]
