; --------------------------------------------------------------------
; In-game tune data (In the Hall of the Mountain King)
;
; Used by the routine at LOOP.
; --------------------------------------------------------------------
GAMETUNE:
        DEFB  128,114,102,96,86,102,86,86,81,96,81,81,86,102,86,86 ;                              [34188]
        DEFB  128,114,102,96,86,102,86,86,81,96,81,81,86,86,86,86 ;                              [34204]
        DEFB  128,114,102,96,86,102,86,86,81,96,81,81,86,102,86,86 ;                              [34220]
        DEFB  128,114,102,96,86,102,86,64,86,102,128,102,86,86,86,86 ;                              [34236]
; --------------------------------------------------------------------
; Display the title screen and play the theme tune
;
; Used by the routines at BEGIN, LOOP and ENDGAM.
; .
; The first thing this routine does is initialise some game status buffer
; variables in preparation for the next game.
; --------------------------------------------------------------------
START:
        XOR   A                      ; A=0      [34252]
        LD    (SHEET),A              ; Initialise the current cavern number at SHEET      [34253]
        LD    (KEMP),A               ; Initialise the Kempston joystick indicator at KEMP      [34256]
        LD    (DEMO),A               ; Initialise the game mode indicator at DEMO      [34259]
        LD    (NOTEINDEX),A          ; Initialise the in-game music note index at NOTEINDEX      [34262]
        LD    (FLASH),A              ; Initialise the screen flash counter at FLASH      [34265]
        LD    A,2                    ; Initialise the number of lives remaining at NOMEN      [34268]
        LD    (NOMEN),A              ;                              [34270]
        LD    HL,MUSICFLAGS          ; Initialise the keypress flag in bit 0 at MUSICFLAGS      [34273]
        SET   0,(HL)                 ;                              [34276]
; --------------------------------------------------------------------
; Next, prepare the screen.
; --------------------------------------------------------------------
        LD    HL,16384               ; Clear the entire display file      [34278]
        LD    DE,16385               ;                              [34281]
        LD    BC,6143                ;                              [34284]
        LD    (HL),0                 ;                              [34287]
        LDIR                         ;                              [34289]
        LD    HL,TITLESCR1           ; Copy the graphic data at TITLESCR1 to the top two-thirds      [34291]
        LD    DE,16384               ; of the display file      [34294]
        LD    BC,4096                ;                              [34297]
        LDIR                         ;                              [34300]
        LD    HL,18493               ; Draw Willy at (9,29)      [34302]
        LD    DE,WILLYR2             ;                              [34305]
        LD    C,0                    ;                              [34308]
        CALL  DRWFIX                 ;                              [34310]
        LD    HL,CAVERN19            ; Copy the attribute bytes from CAVERN19 to the top third      [34313]
        LD    DE,22528               ; of the attribute file      [34316]
        LD    BC,256                 ;                              [34319]
        LDIR                         ;                              [34322]
        LD    HL,LOWERATTRS          ; Copy the attribute bytes from LOWERATTRS to the bottom      [34324]
        LD    BC,512                 ; two-thirds of the attribute file      [34327]
        LDIR                         ;                              [34330]
; --------------------------------------------------------------------
; Now check whether there is a joystick connected.
; --------------------------------------------------------------------
        LD    BC,31                  ; This is the joystick port      [34332]
        DI                           ; Disable interrupts (which are already disabled)      [34335]
        XOR   A                      ; A=0      [34336]
        IN    E,(C)                  ; Combine 256 readings of the joystick port in A; if      [34337]
        OR    E                      ; no joystick is connected, some of these readings will      [34339]
        DJNZ  34337                  ; have bit 5 set      [34340]
        AND   32                     ; Is a joystick connected (bit 5 reset)?      [34342]
        JR    NZ,34351               ; Jump if not      [34344]
        LD    A,1                    ; Set the Kempston joystick indicator at KEMP to 1      [34346]
        LD    (KEMP),A               ;                              [34348]
; --------------------------------------------------------------------
; And finally, play the theme tune and check for keypresses.
; .
; 1,34351,34358(tune.wav)
; --------------------------------------------------------------------
        LD    IY,THEMETUNE           ; Point IY at the theme tune data at THEMETUNE      [34351]
        CALL  PLAYTUNE               ; Play the theme tune      [34355]
        JP    NZ,STARTGAME           ; Start the game if ENTER or the fire button was pressed      [34358]
        XOR   A                      ; Initialise the game status buffer variable at EUGHGT;      [34361]
        LD    (EUGHGT),A             ; this will be used as an index for the message scrolled      [34362]
                                     ;   across the screen
        LD    A,(EUGHGT)             ; Pick up the message index from EUGHGT      [34365]
        LD    IX,MESSINTRO           ; Point IX at the corresponding location in the      [34368]
        LD    IXl,A                  ; message at MESSINTRO      [34372]
        LD    DE,20576               ; Print 32 characters of the message at (19,0)      [34374]
        LD    C,32                   ;                              [34377]
        CALL  PMESS                  ;                              [34379]
        LD    A,(EUGHGT)             ; Pick up the message index from EUGHGT      [34382]
        AND   6                      ; Keep only bits 1 and 2, and move them into bits 6 and      [34385]
        RRCA                         ; 7, so that A holds #b0, #b64, #b128 or #b192; this      [34387]
        RRCA                         ; value determines the animation frame to use for Willy      [34388]
        RRCA                         ;                              [34389]
        LD    E,A                    ; Point DE at the graphic data for Willy's sprite      [34390]
        LD    D,130                  ; (MANDAT+A)      [34391]
        LD    HL,18493               ; Draw Willy at (9,29)      [34393]
        LD    C,0                    ;                              [34396]
        CALL  DRWFIX                 ;                              [34398]
        LD    BC,100                 ; Pause for about 0.1s      [34401]
        DJNZ  34404                  ;                              [34404]
        DEC   C                      ;                              [34406]
        JR    NZ,34404               ;                              [34407]
        LD    BC,49150               ; Read keys H-J-K-L-ENTER      [34409]
        IN    A,(C)                  ;                              [34412]
        AND   1                      ; Keep only bit 0 of the result (ENTER)      [34414]
        CP    1                      ; Is ENTER being pressed?      [34416]
        JR    NZ,STARTGAME           ; If so, start the game      [34418]
        LD    A,(EUGHGT)             ; Pick up the message index from EUGHGT      [34420]
        INC   A                      ; Increment it      [34423]
        CP    224                    ; Set the zero flag if we've reached the end of the      [34424]
                                     ;   message
        LD    (EUGHGT),A             ; Store the new message index at EUGHGT      [34426]
        JR    NZ,34365               ; Jump back unless we've finished scrolling the message      [34429]
                                     ;   across the screen
        LD    A,64                   ; Initialise the game mode indicator at DEMO to #b64:      [34431]
        LD    (DEMO),A               ; demo mode      [34433]
; --------------------------------------------------------------------
; Start the game (or demo mode)
;
; Used by the routine at START.
; --------------------------------------------------------------------
STARTGAME:
        LD    HL,SCORE               ; Initialise the score at SCORE      [34436]
        LD    DE,33830               ;                              [34439]
        LD    BC,9                   ;                              [34442]
        LD    (HL),48                ;                              [34445]
        LDIR                         ;                              [34447]
; --------------------------------------------------------------------
; This entry point is used by the routines at LOOP (when teleporting into a
; cavern or reinitialising the current cavern after Willy has lost a life) and
; NXSHEET.
; --------------------------------------------------------------------
NEWSHT:
        LD    A,(SHEET)              ; Pick up the number of the current cavern from SHEET      [34449]
        SLA   A                      ; Point HL at the first byte of the cavern definition      [34452]
        SLA   A                      ;                              [34454]
        ADD   A,176                  ;                              [34456]
        LD    H,A                    ;                              [34458]
        LD    L,0                    ;                              [34459]
        LD    DE,24064               ; Copy the cavern's attribute bytes into the buffer at      [34461]
        LD    BC,512                 ; 24064      [34464]
        LDIR                         ;                              [34467]
        LD    DE,CAVERNNAME          ; Copy the rest of the cavern definition into the game      [34469]
        LD    BC,512                 ; status buffer at 32768      [34472]
        LDIR                         ;                              [34475]
        CALL  DRAWSHEET              ; Draw the current cavern to the screen buffer at 28672      [34477]
        LD    HL,20480               ; Clear the bottom third of the display file      [34480]
        LD    DE,20481               ;                              [34483]
        LD    BC,2047                ;                              [34486]
        LD    (HL),0                 ;                              [34489]
        LDIR                         ;                              [34491]
        LD    IX,CAVERNNAME          ; Print the cavern name (see CAVERNNAME) at (16,0)      [34493]
        LD    C,32                   ;                              [34497]
        LD    DE,20480               ;                              [34499]
        CALL  PMESS                  ;                              [34502]
        LD    IX,MESSAIR             ; Print 'AIR' (see MESSAIR) at (17,0)      [34505]
        LD    C,3                    ;                              [34509]
        LD    DE,20512               ;                              [34511]
        CALL  PMESS                  ;                              [34514]
        LD    A,82                   ; Initialise A to #b82; this is the MSB of the display      [34517]
                                     ;   file address at which to start drawing the bar that
                                     ;   represents the air supply
        LD    H,A                    ; Prepare HL and DE for drawing a row of pixels      [34519]
        LD    D,A                    ; in the air bar      [34520]
        LD    L,36                   ;                              [34521]
        LD    E,37                   ;                              [34523]
        LD    B,A                    ; Save the display file address MSB in B briefly      [34525]
        LD    A,(AIR)                ; Pick up the value of the initial air supply from AIR      [34526]
        SUB   36                     ; Now C determines the length of the air bar (in cell      [34529]
        LD    C,A                    ; widths)      [34531]
        LD    A,B                    ; Restore the display file address MSB to A      [34532]
        LD    B,0                    ; Now BC determines the length of the air bar (in cell      [34533]
                                     ;   widths)
        LD    (HL),255               ; Draw a single row of pixels across C cells      [34535]
        LDIR                         ;                              [34537]
        INC   A                      ; Increment the display file address MSB in A (moving      [34539]
                                     ;   down to the next row of pixels)
        CP    86                     ; Have we drawn all four rows of pixels in the air bar      [34540]
                                     ;   yet?
        JR    NZ,34519               ; If not, jump back to draw the next one      [34542]
        LD    IX,MESSHSSC            ; Print 'High Score 000000Score 000000' (see      [34544]
        LD    DE,20576               ; MESSHSSC) at (19,0)      [34548]
        LD    C,32                   ;                              [34551]
        CALL  PMESS                  ;                              [34553]
        LD    A,(BORDER)             ; Pick up the border colour for the current cavern from      [34556]
                                     ;   BORDER
        LD    C,254                  ; Set the border colour      [34559]
        OUT   (C),A                  ;                              [34561]
        LD    A,(DEMO)               ; Pick up the game mode indicator from DEMO      [34563]
        OR    A                      ; Are we in demo mode?      [34566]
        JR    Z,LOOP                 ; If not, enter the main loop now      [34567]
        LD    A,64                   ; Reset the game mode indicator at DEMO to #b64 (we're      [34569]
        LD    (DEMO),A               ; in demo mode)      [34571]
; --------------------------------------------------------------------
; Main loop
;
; The routine at STARTGAME continues here.
; .
; The first thing to do is check whether there are any remaining lives to draw
; at the bottom of the screen.
; --------------------------------------------------------------------
LOOP:
        LD    A,(NOMEN)              ; Pick up the number of lives remaining from NOMEN      [34574]
        LD    HL,20640               ; Set HL to the display file address at which to draw      [34577]
                                     ;   the first Willy sprite
        OR    A                      ; Are there any lives remaining?      [34580]
        JR    Z,34608                ; Jump if not      [34581]
        LD    B,A                    ; Initialise B to the number of lives remaining      [34583]
; --------------------------------------------------------------------
; The following loop draws the remaining lives at the bottom of the screen.
; --------------------------------------------------------------------
        LD    C,0                    ; C=0; this tells the sprite-drawing routine at      [34584]
                                     ;   DRWFIX to overwrite any existing graphics
        PUSH  HL                     ; Save HL and BC briefly      [34586]
        PUSH  BC                     ;                              [34587]
        LD    A,(NOTEINDEX)          ; Pick up the in-game music note index from NOTEINDEX; this      [34588]
                                     ;   will determine the animation frame for the Willy sprites
        RLCA                         ; Now A=#b0 (frame 0), #b32 (frame 1), #b64 (frame 2)      [34591]
        RLCA                         ; or #b96 (frame 3)      [34592]
        RLCA                         ;                              [34593]
        AND   96                     ;                              [34594]
        LD    E,A                    ; Point DE at the corresponding Willy sprite (at      [34596]
        LD    D,130                  ; MANDAT+A)      [34597]
        CALL  DRWFIX                 ; Draw the Willy sprite on the screen      [34599]
        POP   BC                     ; Restore HL and BC      [34602]
        POP   HL                     ;                              [34603]
        INC   HL                     ; Move HL along to the location at which to draw the      [34604]
        INC   HL                     ; next Willy sprite      [34605]
        DJNZ  34584                  ; Jump back to draw any remaining sprites      [34606]
; --------------------------------------------------------------------
; Now draw a boot if cheat mode has been activated.
; --------------------------------------------------------------------
        LD    A,(CHEAT)              ; Pick up the 6031769 key counter from CHEAT      [34608]
        CP    7                      ; Has 6031769 been keyed in yet?      [34611]
        JR    NZ,34623               ; Jump if not      [34613]
        LD    DE,BOOT                ; Point DE at the graphic data for the boot (at      [34615]
                                     ;   BOOT)
        LD    C,0                    ; C=0 (overwrite mode)      [34618]
        CALL  DRWFIX                 ; Draw the boot at the bottom of the screen next to the      [34620]
                                     ;   remaining lives
; --------------------------------------------------------------------
; Next, prepare the screen and attribute buffers for drawing to the screen.
; --------------------------------------------------------------------
        LD    HL,24064               ; Copy the contents of the attribute buffer at 24064      [34623]
        LD    DE,23552               ; (the attributes for the empty cavern) into the attribute      [34626]
