        AND   3                      ; Keep only bits 0 (right) and 1 (left) and flip them      [35887]
        CPL                          ;                              [35889]
        AND   E                      ; Merge this reading of the joystick right and left      [35890]
        LD    E,A                    ; buttons into bits 0 and 1 of E      [35891]
; --------------------------------------------------------------------
; At this point, bits 0-5 in E indicate the direction in which Willy is
; being moved or trying to move. If bit 0, 2 or 4 is reset, Willy is being
; moved or trying to move right; if bit 1, 3 or 5 is reset, Willy is being
; moved or trying to move left.
; --------------------------------------------------------------------
        LD    C,0                    ; Initialise C to 0 (no movement)      [35892]
        LD    A,E                    ; Copy the movement bits into A      [35894]
        AND   42                     ; Keep only bits 1, 3 and 5 (the 'left' bits)      [35895]
        CP    42                     ; Are any of these bits reset?      [35897]
        JR    Z,35903                ; Jump if not      [35899]
        LD    C,4                    ; Set bit 2 of C: Willy is moving left      [35901]
        LD    A,E                    ; Copy the movement bits into A      [35903]
        AND   21                     ; Keep only bits 0, 2 and 4 (the 'right' bits)      [35904]
        CP    21                     ; Are any of these bits reset?      [35906]
        JR    Z,35912                ; Jump if not      [35908]
        SET   3,C                    ; Set bit 3 of C: Willy is moving right      [35910]
        LD    A,(DMFLAGS)            ; Pick up Willy's direction and movement flags from      [35912]
                                     ;   DMFLAGS
        ADD   A,C                    ; Point HL at the entry in the left-right movement      [35915]
        LD    C,A                    ; table at LRMOVEMENT that corresponds to the direction Willy      [35916]
        LD    B,0                    ; is facing, and the direction in which he is being moved      [35917]
        LD    HL,LRMOVEMENT          ; or trying to move      [35919]
        ADD   HL,BC                  ;                              [35922]
        LD    A,(HL)                 ; Update Willy's direction and movement flags at DMFLAGS      [35923]
        LD    (DMFLAGS),A            ; with the entry from the left-right movement table      [35924]
; --------------------------------------------------------------------
; That is left-right movement taken care of. Now check the jump keys.
; --------------------------------------------------------------------
        LD    BC,32510               ; Read keys SHIFT-Z-X-C-V and B-N-M-SS-SPACE      [35927]
        IN    A,(C)                  ;                              [35930]
        AND   31                     ; Are any of these keys being pressed?      [35932]
        CP    31                     ;                              [35934]
        JR    NZ,35963               ; Jump if so      [35936]
        LD    B,239                  ; Read keys 0-9-8-7-6 into bits 0-4 of A      [35938]
        IN    A,(C)                  ;                              [35940]
        AND   9                      ; Keep only bits 0 (the '0' key) and 3 (the '7' key)      [35942]
        CP    9                      ; Is '0' or '7' being pressed?      [35944]
        JR    NZ,35963               ; Jump if so      [35946]
        LD    A,(KEMP)               ; Collect the Kempston joystick indicator from KEMP      [35948]
        OR    A                      ; Is the joystick connected?      [35951]
        JR    Z,35971                ; Jump if not      [35952]
        LD    BC,31                  ; Collect input from the joystick      [35954]
        IN    A,(C)                  ;                              [35957]
        BIT   4,A                    ; Is the fire button being pressed?      [35959]
        JR    Z,35971                ; Jump if not      [35961]
; --------------------------------------------------------------------
; A jump key or the fire button is being pressed. Time to make Willy jump.
; --------------------------------------------------------------------
        XOR   A                      ; Initialise the jumping animation counter at JUMPING      [35963]
        LD    (JUMPING),A            ;                              [35964]
        INC   A                      ; Set the airborne status indicator at AIRBORNE to 1:      [35967]
        LD    (AIRBORNE),A           ; Willy is jumping      [35968]
; --------------------------------------------------------------------
; This entry point is used by the routine at MOVEWILLY.
; --------------------------------------------------------------------
        LD    A,(DMFLAGS)            ; Pick up Willy's direction and movement flags from      [35971]
                                     ;   DMFLAGS
        AND   2                      ; Is Willy moving?      [35974]
        RET   Z                      ; Return if not      [35976]
        LD    A,(DMFLAGS)            ; Pick up Willy's direction and movement flags from      [35977]
                                     ;   DMFLAGS
        AND   1                      ; Is Willy facing right?      [35980]
        JP    Z,36042                ; Jump if so      [35982]
; --------------------------------------------------------------------
; Willy is moving left.
; --------------------------------------------------------------------
        LD    A,(FRAME)              ; Pick up Willy's animation frame from FRAME      [35985]
        OR    A                      ; Is it 0?      [35988]
        JR    Z,35996                ; If so, jump to move Willy's sprite left across a cell      [35989]
                                     ;   boundary
        DEC   A                      ; Decrement Willy's animation frame at FRAME      [35991]
        LD    (FRAME),A              ;                              [35992]
        RET                          ;                              [35995]
; --------------------------------------------------------------------
; Willy's sprite is moving left across a cell boundary. In the comments that
; follow, (x,y) refers to the coordinates of the top-left cell currently
; occupied by Willy's sprite.
; --------------------------------------------------------------------
        LD    HL,(LOCATION)          ; Collect Willy's attribute buffer coordinates from      [35996]
                                     ;   LOCATION
        DEC   HL                     ; Point HL at the cell at (x-1,y+1)      [35999]
        LD    DE,32                  ;                              [36000]
        ADD   HL,DE                  ;                              [36003]
        LD    A,(WALL)               ; Pick up the attribute byte of the wall tile for the      [36004]
                                     ;   current cavern from WALL
        CP    (HL)                   ; Is there a wall tile in the cell pointed to by HL?      [36007]
        RET   Z                      ; Return if so without moving Willy (his path is blocked)      [36008]
        LD    A,(WILLY_Y)            ; Pick up Willy's y-coordinate from WILLY_Y      [36009]
        AND   15                     ; Does Willy's sprite currently occupy only two rows of      [36012]
                                     ;   cells?
        JR    Z,36025                ; Jump if so      [36014]
        LD    A,(WALL)               ; Pick up the attribute byte of the wall tile for the      [36016]
                                     ;   current cavern from WALL
        ADD   HL,DE                  ; Point HL at the cell at (x-1,y+2)      [36019]
        CP    (HL)                   ; Is there a wall tile in the cell pointed to by HL?      [36020]
        RET   Z                      ; Return if so without moving Willy (his path is blocked)      [36021]
        OR    A                      ; Clear the carry flag for subtraction      [36022]
        SBC   HL,DE                  ; Point HL at the cell at (x-1,y+1)      [36023]
        LD    A,(WALL)               ; Pick up the attribute byte of the wall tile for the      [36025]
                                     ;   current cavern from WALL
        OR    A                      ; Clear the carry flag for subtraction      [36028]
        SBC   HL,DE                  ; Point HL at the cell at (x-1,y)      [36029]
        CP    (HL)                   ; Is there a wall tile in the cell pointed to by HL?      [36031]
        RET   Z                      ; Return if so without moving Willy (his path is blocked)      [36032]
        LD    (LOCATION),HL          ; Save Willy's new attribute buffer coordinates (in      [36033]
                                     ;   HL) at LOCATION
        LD    A,3                    ; Change Willy's animation frame at FRAME from 0 to 3      [36036]
        LD    (FRAME),A              ;                              [36038]
        RET                          ;                              [36041]
; --------------------------------------------------------------------
; Willy is moving right.
; --------------------------------------------------------------------
        LD    A,(FRAME)              ; Pick up Willy's animation frame from FRAME      [36042]
        CP    3                      ; Is it 3?      [36045]
        JR    Z,36054                ; If so, jump to move Willy's sprite right across a cell      [36047]
                                     ;   boundary
        INC   A                      ; Increment Willy's animation frame at FRAME      [36049]
        LD    (FRAME),A              ;                              [36050]
        RET                          ;                              [36053]
; --------------------------------------------------------------------
; Willy's sprite is moving right across a cell boundary. In the comments that
; follow, (x,y) refers to the coordinates of the top-left cell currently
; occupied by Willy's sprite.
; --------------------------------------------------------------------
        LD    HL,(LOCATION)          ; Collect Willy's attribute buffer coordinates from      [36054]
                                     ;   LOCATION
        INC   HL                     ; Point HL at the cell at (x+2,y)      [36057]
        INC   HL                     ;                              [36058]
        LD    DE,32                  ; Prepare DE for addition      [36059]
        LD    A,(WALL)               ; Pick up the attribute byte of the wall tile for the      [36062]
                                     ;   current cavern from WALL
        ADD   HL,DE                  ; Point HL at the cell at (x+2,y+1)      [36065]
        CP    (HL)                   ; Is there a wall tile in the cell pointed to by HL?      [36066]
        RET   Z                      ; Return if so without moving Willy (his path is blocked)      [36067]
        LD    A,(WILLY_Y)            ; Pick up Willy's y-coordinate from WILLY_Y      [36068]
        AND   15                     ; Does Willy's sprite currently occupy only two rows of      [36071]
                                     ;   cells?
        JR    Z,36084                ; Jump if so      [36073]
        LD    A,(WALL)               ; Pick up the attribute byte of the wall tile for the      [36075]
                                     ;   current cavern from WALL
        ADD   HL,DE                  ; Point HL at the cell at (x+2,y+2)      [36078]
        CP    (HL)                   ; Is there a wall tile in the cell pointed to by HL?      [36079]
        RET   Z                      ; Return if so without moving Willy (his path is blocked)      [36080]
        OR    A                      ; Clear the carry flag for subtraction      [36081]
        SBC   HL,DE                  ; Point HL at the cell at (x+2,y+1)      [36082]
        LD    A,(WALL)               ; Pick up the attribute byte of the wall tile for the      [36084]
                                     ;   current cavern from WALL
        OR    A                      ; Clear the carry flag for subtraction      [36087]
        SBC   HL,DE                  ; Point HL at the cell at (x+2,y)      [36088]
        CP    (HL)                   ; Is there a wall tile in the cell pointed to by HL?      [36090]
        RET   Z                      ; Return if so without moving Willy (his path is blocked)      [36091]
        DEC   HL                     ; Point HL at the cell at (x+1,y)      [36092]
        LD    (LOCATION),HL          ; Save Willy's new attribute buffer coordinates (in      [36093]
                                     ;   HL) at LOCATION
        XOR   A                      ; Change Willy's animation frame at FRAME from 3 to 0      [36096]
        LD    (FRAME),A              ;                              [36097]
        RET                          ;                              [36100]
; --------------------------------------------------------------------
; Kill Willy
;
; Used by the routine at WILLYATTR when Willy hits a nasty.
; --------------------------------------------------------------------
KILLWILLY:
        POP   HL                     ; Drop the return address from the stack      [36101]
; --------------------------------------------------------------------
; This entry point is used by the routines at MOVEWILLY2 (when Willy lands after
; falling from too great a height), DRAWHG (when Willy collides with a
; horizontal guardian), EUGENE (when Willy collides with Eugene), VGUARDIANS
; (when Willy collides with a vertical guardian) and KONGBEAST (when Willy
; collides with the Kong Beast).
; --------------------------------------------------------------------
        POP   HL                     ; Drop the return address from the stack      [36102]
; --------------------------------------------------------------------
; This entry point is used by the routine at SKYLABS when a Skylab falls on
; Willy.
; --------------------------------------------------------------------
        LD    A,255                  ; Set the airborne status indicator at AIRBORNE to #b255      [36103]
        LD    (AIRBORNE),A           ; (meaning Willy has had a fatal accident)      [36105]
        JP    34722                  ; Jump back into the main loop      [36108]
; --------------------------------------------------------------------
; Move the horizontal guardians in the current cavern
;
; Used by the routine at LOOP.
; --------------------------------------------------------------------
MOVEHG:
        LD    IY,HGUARDS             ; Point IY at the first byte of the first horizontal      [36111]
                                     ;   guardian definition at HGUARDS
        LD    DE,7                   ; Prepare DE for addition (there are 7 bytes in a      [36115]
                                     ;   guardian definition)
; --------------------------------------------------------------------
; The guardian-moving loop begins here.
; --------------------------------------------------------------------
        LD    A,(IY+0)               ; Pick up the first byte of the guardian definition      [36118]
        CP    255                    ; Have we dealt with all the guardians yet?      [36121]
        RET   Z                      ; Return if so      [36123]
        OR    A                      ; Is this guardian definition blank?      [36124]
        JR    Z,36207                ; If so, skip it and consider the next one      [36125]
        LD    A,(CLOCK)              ; Pick up the value of the game clock at CLOCK      [36127]
        AND   4                      ; Move bit 2 (which is toggled on each pass through the      [36130]
        RRCA                         ; main loop) to bit 7 and clear all the other bits      [36132]
        RRCA                         ;                              [36133]
        RRCA                         ;                              [36134]
        AND   (IY+0)                 ; Combine this bit with bit 7 of the first byte of the      [36135]
                                     ;   guardian definition, which specifies the guardian's
                                     ;   animation speed: 0=normal, 1=slow
        JR    NZ,36207               ; Jump to consider the next guardian if this one is not      [36138]
                                     ;   due to be moved on this pass
; --------------------------------------------------------------------
; The guardian will be moved on this pass.
; --------------------------------------------------------------------
        LD    A,(IY+4)               ; Pick up the current animation frame (0-7)      [36140]
        CP    3                      ; Is it 3 (the terminal frame for a guardian moving      [36143]
                                     ;   right)?
        JR    Z,36163                ; Jump if so to move the guardian right across a cell      [36145]
                                     ;   boundary or turn it round
        CP    4                      ; Is the current animation frame 4 (the terminal frame for      [36147]
                                     ;   a guardian moving left)?
        JR    Z,36186                ; Jump if so to move the guardian left across a cell      [36149]
                                     ;   boundary or turn it round
        JR    NC,36158               ; Jump if the animation frame is 5, 6 or 7      [36151]
        INC   (IY+4)                 ; Increment the animation frame (this guardian is moving      [36153]
                                     ;   right)
        JR    36207                  ; Jump forward to consider the next guardian      [36156]
        DEC   (IY+4)                 ; Decrement the animation frame (this guardian is moving      [36158]
                                     ;   left)
        JR    36207                  ; Jump forward to consider the next guardian      [36161]
        LD    A,(IY+1)               ; Pick up the LSB of the address of the guardian's      [36163]
                                     ;   location in the attribute buffer at 23552
        CP    (IY+6)                 ; Has the guardian reached the rightmost point in its      [36166]
                                     ;   path?
        JR    NZ,36177               ; Jump if not      [36169]
        LD    (IY+4),7               ; Set the animation frame to 7 (turning the guardian round      [36171]
                                     ;   to face left)
        JR    36207                  ; Jump forward to consider the next guardian      [36175]
        LD    (IY+4),0               ; Set the animation frame to 0 (the initial frame for a      [36177]
                                     ;   guardian moving right)
        INC   (IY+1)                 ; Increment the guardian's x-coordinate (moving it right      [36181]
                                     ;   across a cell boundary)
        JR    36207                  ; Jump forward to consider the next guardian      [36184]
        LD    A,(IY+1)               ; Pick up the LSB of the address of the guardian's      [36186]
                                     ;   location in the attribute buffer at 23552
        CP    (IY+5)                 ; Has the guardian reached the leftmost point in its path?      [36189]
        JR    NZ,36200               ; Jump if not      [36192]
        LD    (IY+4),0               ; Set the animation frame to 0 (turning the guardian round      [36194]
                                     ;   to face right)
        JR    36207                  ; Jump forward to consider the next guardian      [36198]
        LD    (IY+4),7               ; Set the animation frame to 7 (the initial frame for a      [36200]
                                     ;   guardian moving left)
        DEC   (IY+1)                 ; Decrement the guardian's x-coordinate (moving it left      [36204]
                                     ;   across a cell boundary)
; --------------------------------------------------------------------
; The current guardian definition has been dealt with. Time for the next one.
; --------------------------------------------------------------------
        ADD   IY,DE                  ; Point IY at the first byte of the next horizontal      [36207]
                                     ;   guardian definition
        JR    36118                  ; Jump back to deal with the next horizontal guardian      [36209]
; --------------------------------------------------------------------
; Move and draw the light beam in Solar Power Generator
;
; Used by the routine at LOOP.
; --------------------------------------------------------------------
LIGHTBEAM:
        LD    HL,23575               ; Point HL at the cell at (0,23) in the attribute      [36211]
                                     ;   buffer at 23552 (the source of the light beam)
        LD    DE,32                  ; Prepare DE for addition (the beam travels vertically      [36214]
                                     ;   downwards to start with)
; --------------------------------------------------------------------
; The beam-drawing loop begins here.
; --------------------------------------------------------------------
        LD    A,(FLOOR)              ; Pick up the attribute byte of the floor tile for the      [36217]
                                     ;   cavern from FLOOR
        CP    (HL)                   ; Does HL point at a floor tile?      [36220]
        RET   Z                      ; Return if so (the light beam stops here)      [36221]
        LD    A,(WALL)               ; Pick up the attribute byte of the wall tile for the      [36222]
                                     ;   cavern from WALL
        CP    (HL)                   ; Does HL point at a wall tile?      [36225]
        RET   Z                      ; Return if so (the light beam stops here)      [36226]
        LD    A,39                   ; A=#b39 (INK 7: PAPER 4)      [36227]
        CP    (HL)                   ; Does HL point at a tile with this attribute value?      [36229]
        JR    NZ,36248               ; Jump if not (the light beam is not touching Willy)      [36230]
        EXX                          ; Switch to the shadow registers briefly (to preserve      [36232]
                                     ;   DE and HL)
        CALL  DECAIR                 ; Decrease the air supply by four units      [36233]
        CALL  DECAIR                 ;                              [36236]
        CALL  DECAIR                 ;                              [36239]
        CALL  DECAIR                 ;                              [36242]
        EXX                          ; Switch back to the normal registers (restoring DE      [36245]
                                     ;   and HL)
        JR    36261                  ; Jump forward to draw the light beam over Willy      [36246]
        LD    A,(BACKGROUND)         ; Pick up the attribute byte of the background tile for      [36248]
                                     ;   the cavern from BACKGROUND
        CP    (HL)                   ; Does HL point at a background tile?      [36251]
        JR    Z,36261                ; Jump if so (the light beam will not be reflected at this      [36252]
                                     ;   point)
        LD    A,E                    ; Toggle the value in DE between 32 and -1 (and      [36254]
        XOR   223                    ; therefore the direction of the light beam between      [36255]
        LD    E,A                    ; vertically downwards and horizontally to the left): the      [36257]
        LD    A,D                    ; light beam has hit a guardian      [36258]
        CPL                          ;                              [36259]
        LD    D,A                    ;                              [36260]
        LD    (HL),119               ; Draw a portion of the light beam with attribute value      [36261]
                                     ;   #b119 (INK 7: PAPER 6: BRIGHT 1)
        ADD   HL,DE                  ; Point HL at the cell where the next portion of the      [36263]
                                     ;   light beam will be drawn
        JR    36217                  ; Jump back to draw the next portion of the light beam      [36264]
; --------------------------------------------------------------------
; Draw the horizontal guardians in the current cavern
;
; Used by the routine at LOOP.
; --------------------------------------------------------------------
DRAWHG:
        LD    IY,HGUARDS             ; Point IY at the first byte of the first horizontal      [36266]
                                     ;   guardian definition at HGUARDS
; --------------------------------------------------------------------
; The guardian-drawing loop begins here.
; --------------------------------------------------------------------
        LD    A,(IY+0)               ; Pick up the first byte of the guardian definition      [36270]
        CP    255                    ; Have we dealt with all the guardians yet?      [36273]
        RET   Z                      ; Return if so      [36275]
        OR    A                      ; Is this guardian definition blank?      [36276]
        JR    Z,36337                ; If so, skip it and consider the next one      [36277]
        LD    DE,31                  ; Prepare DE for addition      [36279]
        LD    L,(IY+1)               ; Point HL at the address of the guardian's location      [36282]
        LD    H,(IY+2)               ; in the attribute buffer at 23552      [36285]
        AND   127                    ; Reset bit 7 (which specifies the animation speed) of the      [36288]
                                     ;   attribute byte, ensuring no FLASH
        LD    (HL),A                 ; Set the attribute bytes for the guardian in the buffer      [36290]
        INC   HL                     ; at 23552      [36291]
        LD    (HL),A                 ;                              [36292]
        ADD   HL,DE                  ;                              [36293]
        LD    (HL),A                 ;                              [36294]
        INC   HL                     ;                              [36295]
        LD    (HL),A                 ;                              [36296]
        LD    C,1                    ; Prepare C for the call to the drawing routine at      [36297]
                                     ;   DRWFIX later on
        LD    A,(IY+4)               ; Pick up the animation frame (0-7)      [36299]
        RRCA                         ; Multiply it by 32      [36302]
        RRCA                         ;                              [36303]
        RRCA                         ;                              [36304]
        LD    E,A                    ; Copy the result to E      [36305]
        LD    A,(SHEET)              ; Pick up the number of the current cavern from SHEET      [36306]
        CP    7                      ; Are we in one of the first seven caverns?      [36309]
        JR    C,36323                ; Jump if so      [36311]
        CP    9                      ; Are we in CAVERN9(The Endorian Forest)?      [36313]
        JR    Z,36323                ; Jump if so      [36315]
        CP    15                     ; Are we in CAVERN15(The Sixteenth Cavern)?      [36317]
        JR    Z,36323                ; Jump if so      [36319]
        SET   7,E                    ; Add #b128 to E (the horizontal guardians in this      [36321]
                                     ;   cavern use frames 4-7 only)
        LD    D,129                  ; Point DE at the graphic data for the appropriate      [36323]
                                     ;   guardian sprite (at GGDATA+E)
        LD    L,(IY+1)               ; Point HL at the address of the guardian's location      [36325]
        LD    H,(IY+3)               ; in the screen buffer at 24576      [36328]
        CALL  DRWFIX                 ; Draw the guardian to the screen buffer at 24576      [36331]
        JP    NZ,36102               ; Kill Willy if the guardian collided with him      [36334]
; --------------------------------------------------------------------
; The current guardian definition has been dealt with. Time for the next one.
; --------------------------------------------------------------------
        LD    DE,7                   ; Point IY at the first byte of the next horizontal      [36337]
        ADD   IY,DE                  ; guardian definition      [36340]
        JR    36270                  ; Jump back to deal with the next horizontal guardian      [36342]
; --------------------------------------------------------------------
; Move and draw Eugene in Eugene's Lair
;
; Used by the routine at LOOP. First we move Eugene up or down, or change
; his direction.
; --------------------------------------------------------------------
EUGENE:
        LD    A,(ITEMATTR)           ; Pick up the attribute of the last item drawn from      [36344]
                                     ;   ITEMATTR
        OR    A                      ; Have all the items been collected?      [36347]
        JR    Z,36367                ; Jump if so      [36348]
        LD    A,(EUGDIR)             ; Pick up Eugene's direction from EUGDIR      [36350]
        OR    A                      ; Is Eugene moving downwards?      [36353]
        JR    Z,36367                ; Jump if so      [36354]
        LD    A,(EUGHGT)             ; Pick up Eugene's pixel y-coordinate from EUGHGT      [36356]
        DEC   A                      ; Decrement it (moving Eugene up)      [36359]
        JR    Z,36380                ; Jump if Eugene has reached the top of the cavern      [36360]
        LD    (EUGHGT),A             ; Update Eugene's pixel y-coordinate at EUGHGT      [36362]
        JR    36388                  ;                              [36365]
        LD    A,(EUGHGT)             ; Pick up Eugene's pixel y-coordinate from EUGHGT      [36367]
        INC   A                      ; Increment it (moving Eugene down)      [36370]
        CP    88                     ; Has Eugene reached the portal yet?      [36371]
        JR    Z,36380                ; Jump if so      [36373]
        LD    (EUGHGT),A             ; Update Eugene's pixel y-coordinate at EUGHGT      [36375]
        JR    36388                  ;                              [36378]
        LD    A,(EUGDIR)             ; Toggle Eugene's direction at EUGDIR      [36380]
        XOR   1                      ;                              [36383]
        LD    (EUGDIR),A             ;                              [36385]
; --------------------------------------------------------------------
; Now that Eugene's movement has been dealt with, it's time to draw him.
; --------------------------------------------------------------------
        LD    A,(EUGHGT)             ; Pick up Eugene's pixel y-coordinate from EUGHGT      [36388]
        AND   127                    ; Point DE at the entry in the screen buffer address      [36391]
        RLCA                         ; lookup table at SBUFADDRS that corresponds to Eugene's      [36393]
        LD    E,A                    ; y-coordinate      [36394]
        LD    D,131                  ;                              [36395]
        LD    A,(DE)                 ; Point HL at the address of Eugene's location in the      [36397]
        OR    15                     ; screen buffer at 24576      [36398]
        LD    L,A                    ;                              [36400]
        INC   DE                     ;                              [36401]
        LD    A,(DE)                 ;                              [36402]
        LD    H,A                    ;                              [36403]
        LD    DE,32992               ; Draw Eugene to the screen buffer at 24576      [36404]
        LD    C,1                    ;                              [36407]
        CALL  DRWFIX                 ;                              [36409]
        JP    NZ,36102               ; Kill Willy if Eugene collided with him      [36412]
        LD    A,(EUGHGT)             ; Pick up Eugene's pixel y-coordinate from EUGHGT      [36415]
        AND   120                    ; Point HL at the address of Eugene's location in the      [36418]
        RLCA                         ; attribute buffer at 23552      [36420]
        OR    7                      ;                              [36421]
        SCF                          ;                              [36423]
        RL    A                      ;                              [36424]
        LD    L,A                    ;                              [36426]
        LD    A,0                    ;                              [36427]
        ADC   A,92                   ;                              [36429]
        LD    H,A                    ;                              [36431]
        LD    A,(ITEMATTR)           ; Pick up the attribute of the last item drawn from      [36432]
                                     ;   ITEMATTR
        OR    A                      ; Set the zero flag if all the items have been collected      [36435]
        LD    A,7                    ; Assume we will draw Eugene with white INK      [36436]
        JR    NZ,36447               ; Jump if there are items remaining to be collected      [36438]
        LD    A,(CLOCK)              ; Pick up the value of the game clock at CLOCK      [36440]
        RRCA                         ; Move bits 2-4 into bits 0-2 and clear the other bits;      [36443]
        RRCA                         ; this value (which decreases by one on each pass through      [36444]
        AND   7                      ; the main loop) will be Eugene's INK colour      [36445]
; --------------------------------------------------------------------
; This entry point is used by the routines at SKYLABS (to set the attributes
; for a Skylab), VGUARDIANS (to set the attributes for a vertical guardian) and
; KONGBEAST (to set the attributes for the Kong Beast).
; --------------------------------------------------------------------
        LD    (HL),A                 ; Save the INK colour in the attribute buffer temporarily      [36447]
        LD    A,(BACKGROUND)         ; Pick up the attribute byte of the background tile for      [36448]
                                     ;   the current cavern from BACKGROUND
        AND   248                    ; Combine its PAPER colour with the chosen INK colour      [36451]
        OR    (HL)                   ;                              [36453]
        LD    (HL),A                 ; Set the attribute byte for the top-left cell of the      [36454]
                                     ;   sprite in the attribute buffer at 23552
        LD    DE,31                  ; Prepare DE for addition      [36455]
        INC   HL                     ; Set the attribute byte for the top-right cell of the      [36458]
        LD    (HL),A                 ; sprite in the attribute buffer at 23552      [36459]
        ADD   HL,DE                  ; Set the attribute byte for the middle-left cell of the      [36460]
        LD    (HL),A                 ; sprite in the attribute buffer at 23552      [36461]
        INC   HL                     ; Set the attribute byte for the middle-right cell of the      [36462]
        LD    (HL),A                 ; sprite in the attribute buffer at 23552      [36463]
        ADD   HL,DE                  ; Set the attribute byte for the bottom-left cell of the      [36464]
        LD    (HL),A                 ; sprite in the attribute buffer at 23552      [36465]
        INC   HL                     ; Set the attribute byte for the bottom-right cell of the      [36466]
        LD    (HL),A                 ; sprite in the attribute buffer at 23552      [36467]
        RET                          ;                              [36468]
; --------------------------------------------------------------------
; Move and draw the Skylabs in Skylab Landing Bay
;
; Used by the routine at LOOP.
; --------------------------------------------------------------------
SKYLABS:
        LD    IY,VGUARDS             ; Point IY at the first byte of the first vertical      [36469]
                                     ;   guardian definition at VGUARDS
; --------------------------------------------------------------------
; The Skylab-moving loop begins here.
; --------------------------------------------------------------------
        LD    A,(IY+0)               ; Pick up the first byte of the guardian definition      [36473]
        CP    255                    ; Have we dealt with all the Skylabs yet?      [36476]
        JP    Z,34719                ; If so, re-enter the main loop      [36478]
        LD    A,(IY+2)               ; Pick up the Skylab's pixel y-coordinate      [36481]
        CP    (IY+6)                 ; Has it reached its crash site yet?      [36484]
        JR    NC,36497               ; Jump if so      [36487]
        ADD   A,(IY+4)               ; Increment the Skylab's y-coordinate (moving it      [36489]
        LD    (IY+2),A               ; downwards)      [36492]
        JR    36527                  ;                              [36495]
; --------------------------------------------------------------------
; The Skylab has reached its crash site. Start or continue its disintegration.
; --------------------------------------------------------------------
        INC   (IY+1)                 ; Increment the animation frame      [36497]
        LD    A,(IY+1)               ; Pick up the animation frame      [36500]
        CP    8                      ; Has the Skylab completely disintegrated yet?      [36503]
        JR    NZ,36527               ; Jump if not      [36505]
        LD    A,(IY+5)               ; Reset the Skylab's pixel y-coordinate      [36507]
        LD    (IY+2),A               ;                              [36510]
        LD    A,(IY+3)               ; Add 8 to the Skylab's x-coordinate (wrapping around at      [36513]
        ADD   A,8                    ; the right side of the screen)      [36516]
        AND   31                     ;                              [36518]
        LD    (IY+3),A               ;                              [36520]
        LD    (IY+1),0               ; Reset the animation frame to 0      [36523]
; --------------------------------------------------------------------
; Now that the Skylab's movement has been dealt with, time to draw it.
; --------------------------------------------------------------------
        LD    E,(IY+2)               ; Pick up the Skylab's pixel y-coordinate in E      [36527]
        RLC   E                      ; Point DE at the entry in the screen buffer address      [36530]
        LD    D,131                  ; lookup table at SBUFADDRS that corresponds to the Skylab's      [36532]
                                     ;   pixel y-coordinate
        LD    A,(DE)                 ; Point HL at the address of the Skylab's location in      [36534]
        ADD   A,(IY+3)               ; the screen buffer at 24576      [36535]
        LD    L,A                    ;                              [36538]
        INC   DE                     ;                              [36539]
        LD    A,(DE)                 ;                              [36540]
        LD    H,A                    ;                              [36541]
        LD    A,(IY+1)               ; Pick up the animation frame (0-7)      [36542]
        RRCA                         ; Multiply it by 32      [36545]
        RRCA                         ;                              [36546]
        RRCA                         ;                              [36547]
        LD    E,A                    ; Point DE at the graphic data for the corresponding      [36548]
        LD    D,129                  ; Skylab sprite (at GGDATA+A)      [36549]
        LD    C,1                    ; Draw the Skylab to the screen buffer at 24576      [36551]
        CALL  DRWFIX                 ;                              [36553]
        JP    NZ,36103               ; Kill Willy if the Skylab collided with him      [36556]
        LD    A,(IY+2)               ; Point HL at the address of the Skylab's location in      [36559]
        AND   64                     ; the attribute buffer at 23552      [36562]
        RLCA                         ;                              [36564]
        RLCA                         ;                              [36565]
        ADD   A,92                   ;                              [36566]
        LD    H,A                    ;                              [36568]
        LD    A,(IY+2)               ;                              [36569]
        RLCA                         ;                              [36572]
        RLCA                         ;                              [36573]
        AND   224                    ;                              [36574]
        OR    (IY+3)                 ;                              [36576]
        LD    L,A                    ;                              [36579]
        LD    A,(IY+0)               ; Pick up the Skylab's attribute byte      [36580]
        CALL  36447                  ; Set the attribute bytes for the Skylab      [36583]
; --------------------------------------------------------------------
; The current guardian definition has been dealt with. Time for the next one.
; --------------------------------------------------------------------
        LD    DE,7                   ; Point IY at the first byte of the next vertical      [36586]
        ADD   IY,DE                  ; guardian definition      [36589]
        JR    36473                  ; Jump back to deal with the next Skylab      [36591]
; --------------------------------------------------------------------
; Move and draw the vertical guardians in the current cavern
;
; Used by the routine at LOOP.
; --------------------------------------------------------------------
VGUARDIANS:
        LD    IY,VGUARDS             ; Point IY at the first byte of the first vertical      [36593]
                                     ;   guardian definition at VGUARDS
; --------------------------------------------------------------------
; The guardian-moving loop begins here.
; --------------------------------------------------------------------
        LD    A,(IY+0)               ; Pick up the first byte of the guardian definition      [36597]
        CP    255                    ; Have we dealt with all the guardians yet?      [36600]
        RET   Z                      ; Return if so      [36602]
        INC   (IY+1)                 ; Increment the guardian's animation frame      [36603]
        RES   2,(IY+1)               ; Reset the animation frame to 0 if it overflowed to 4      [36606]
        LD    A,(IY+2)               ; Pick up the guardian's pixel y-coordinate      [36610]
        ADD   A,(IY+4)               ; Add the current y-coordinate increment      [36613]
        CP    (IY+5)                 ; Has the guardian reached the highest point of its path      [36616]
                                     ;   (minimum y-coordinate)?
        JR    C,36631                ; If so, jump to change its direction of movement      [36619]
        CP    (IY+6)                 ; Has the guardian reached the lowest point of its path      [36621]
                                     ;   (maximum y-coordinate)?
        JR    NC,36631               ; If so, jump to change its direction of movement      [36624]
        LD    (IY+2),A               ; Update the guardian's pixel y-coordinate      [36626]
        JR    36639                  ;                              [36629]
        LD    A,(IY+4)               ; Negate the y-coordinate increment; this changes the      [36631]
        NEG                          ; guardian's direction of movement      [36634]
        LD    (IY+4),A               ;                              [36636]
; --------------------------------------------------------------------
; Now that the guardian's movement has been dealt with, time to draw it.
; --------------------------------------------------------------------
        LD    A,(IY+2)               ; Pick up the guardian's pixel y-coordinate      [36639]
        AND   127                    ; Point DE at the entry in the screen buffer address      [36642]
        RLCA                         ; lookup table at SBUFADDRS that corresponds to the      [36644]
        LD    E,A                    ; guardian's pixel y-coordinate      [36645]
        LD    D,131                  ;                              [36646]
        LD    A,(DE)                 ; Point HL at the address of the guardian's location      [36648]
        OR    (IY+3)                 ; in the screen buffer at 24576      [36649]
        LD    L,A                    ;                              [36652]
        INC   DE                     ;                              [36653]
        LD    A,(DE)                 ;                              [36654]
        LD    H,A                    ;                              [36655]
        LD    A,(IY+1)               ; Pick up the guardian's animation frame (0-3)      [36656]
        RRCA                         ; Multiply it by 32      [36659]
        RRCA                         ;                              [36660]
        RRCA                         ;                              [36661]
        LD    E,A                    ; Point DE at the graphic data for the appropriate      [36662]
        LD    D,129                  ; guardian sprite (at GGDATA+A)      [36663]
        LD    C,1                    ; Draw the guardian to the screen buffer at 24576      [36665]
        CALL  DRWFIX                 ;                              [36667]
        JP    NZ,36102               ; Kill Willy if the guardian collided with him      [36670]
        LD    A,(IY+2)               ; Pick up the guardian's pixel y-coordinate      [36673]
        AND   64                     ; Point HL at the address of the guardian's location      [36676]
        RLCA                         ; in the attribute buffer at 23552      [36678]
        RLCA                         ;                              [36679]
        ADD   A,92                   ;                              [36680]
        LD    H,A                    ;                              [36682]
        LD    A,(IY+2)               ;                              [36683]
        RLCA                         ;                              [36686]
        RLCA                         ;                              [36687]
        AND   224                    ;                              [36688]
        OR    (IY+3)                 ;                              [36690]
        LD    L,A                    ;                              [36693]
        LD    A,(IY+0)               ; Pick up the guardian's attribute byte      [36694]
        CALL  36447                  ; Set the attribute bytes for the guardian      [36697]
; --------------------------------------------------------------------
; The current guardian definition has been dealt with. Time for the next one.
; --------------------------------------------------------------------
        LD    DE,7                   ; Point IY at the first byte of the next vertical      [36700]
        ADD   IY,DE                  ; guardian definition      [36703]
        JR    36597                  ; Jump back to deal with the next vertical guardian      [36705]
; --------------------------------------------------------------------
; Draw the items in the current cavern and collect any that Willy is touching
;
; Used by the routine at LOOP.
; --------------------------------------------------------------------
DRAWITEMS:
        XOR   A                      ; Initialise the attribute of the last item drawn at      [36707]
        LD    (ITEMATTR),A           ; ITEMATTR to #b0 (in case there are no items left to draw)      [36708]
        LD    IY,ITEMS               ; Point IY at the first byte of the first item      [36711]
                                     ;   definition at ITEMS
; --------------------------------------------------------------------
; The item-drawing loop begins here.
; --------------------------------------------------------------------
        LD    A,(IY+0)               ; Pick up the first byte of the item definition      [36715]
        CP    255                    ; Have we dealt with all the items yet?      [36718]
        JR    Z,36794                ; Jump if so      [36720]
        OR    A                      ; Has this item already been collected?      [36722]
        JR    Z,36782                ; If so, skip it and consider the next one      [36723]
        LD    E,(IY+1)               ; Point DE at the address of the item's location in      [36725]
        LD    D,(IY+2)               ; the attribute buffer at 23552      [36728]
        LD    A,(DE)                 ; Pick up the current attribute byte at the item's      [36731]
                                     ;   location
        AND   7                      ; Is the INK white (which happens if Willy is touching      [36732]
        CP    7                      ; the item)?      [36734]
        JR    NZ,36750               ; Jump if not      [36736]
; --------------------------------------------------------------------
; Willy is touching this item, so add it to his collection.
; --------------------------------------------------------------------
        LD    HL,33836               ; Add 100 to the score      [36738]
        CALL  37118                  ;                              [36741]
        LD    (IY+0),0               ; Set the item's attribute byte to #b0 so that it will be      [36744]
                                     ;   skipped the next time
        JR    36782                  ; Jump forward to consider the next item      [36748]
; --------------------------------------------------------------------
; This item has not been collected yet.
; --------------------------------------------------------------------
        LD    A,(IY+0)               ; Pick up the item's current attribute byte      [36750]
        AND   248                    ; Keep the BRIGHT and PAPER bits, and set the INK to 3      [36753]
        OR    3                      ; (magenta)      [36755]
        LD    B,A                    ; Store this value in B      [36757]
        LD    A,(IY+0)               ; Pick up the item's current attribute byte again      [36758]
        AND   3                      ; Keep only bits 0 and 1 and add the value in B; this      [36761]
        ADD   A,B                    ; maintains the BRIGHT and PAPER bits, and cycles the INK      [36763]
                                     ;   colour through 3, 4, 5 and 6
        LD    (IY+0),A               ; Store the new attribute byte      [36764]
        LD    (DE),A                 ; Update the attribute byte at the item's location in the      [36767]
                                     ;   buffer at 23552
        LD    (ITEMATTR),A           ; Store the new attribute byte at ITEMATTR as well      [36768]
        LD    D,(IY+3)               ; Point DE at the address of the item's location in      [36771]
                                     ;   the screen buffer at 24576
        LD    HL,ITEM                ; Point HL at the item graphic for the current cavern      [36774]
                                     ;   (at ITEM)
        LD    B,8                    ; There are eight pixel rows to copy      [36777]
        CALL  37589                  ; Draw the item to the screen buffer at 24576      [36779]
; --------------------------------------------------------------------
; The current item definition has been dealt with. Time for the next one.
; --------------------------------------------------------------------
        INC   IY                     ; Point IY at the first byte of the next item      [36782]
        INC   IY                     ; definition      [36784]
        INC   IY                     ;                              [36786]
        INC   IY                     ;                              [36788]
        INC   IY                     ;                              [36790]
        JR    36715                  ; Jump back to deal with the next item      [36792]
; --------------------------------------------------------------------
; All the items have been dealt with. Check whether there were any left.
; --------------------------------------------------------------------
        LD    A,(ITEMATTR)           ; Pick up the attribute of the last item drawn at ITEMATTR      [36794]
        OR    A                      ; Were any items drawn?      [36797]
        RET   NZ                     ; Return if so (some remain to be collected)      [36798]
        LD    HL,PORTAL              ; Ensure that the portal is flashing by setting bit 7 of      [36799]
        SET   7,(HL)                 ; its attribute byte at PORTAL      [36802]
        RET                          ;                              [36804]
; --------------------------------------------------------------------
; Draw the portal, or move to the next cavern if Willy has entered it
;
; Used by the routine at LOOP. First check whether Willy has entered the
; portal.
; --------------------------------------------------------------------
CHKPORTAL:
        LD    HL,(PORTALLOC1)        ; Pick up the address of the portal's location in the      [36805]
                                     ;   attribute buffer at 23552 from PORTALLOC1
        LD    A,(LOCATION)           ; Pick up the LSB of the address of Willy's location in      [36808]
                                     ;   the attribute buffer at 23552 from LOCATION
        CP    L                      ; Does it match that of the portal?      [36811]
        JR    NZ,36831               ; Jump if not      [36812]
        LD    A,(32877)              ; Pick up the MSB of the address of Willy's location in      [36814]
                                     ;   the attribute buffer at 23552 from LOCATION(32877)
        CP    H                      ; Does it match that of the portal?      [36817]
        JR    NZ,36831               ; Jump if not      [36818]
        LD    A,(PORTAL)             ; Pick up the portal's attribute byte from PORTAL      [36820]
        BIT   7,A                    ; Is the portal flashing?      [36823]
        JR    Z,36831                ; Jump if not      [36825]
        POP   HL                     ; Drop the return address from the stack      [36827]
        JP    NXSHEET                ; Move Willy to the next cavern      [36828]
; --------------------------------------------------------------------
; Willy has not entered the portal, or it's not flashing, so just draw it.
; --------------------------------------------------------------------
        LD    A,(PORTAL)             ; Pick up the portal's attribute byte from PORTAL      [36831]
        LD    (HL),A                 ; Set the attribute bytes for the portal in the buffer at      [36834]
        INC   HL                     ; 23552      [36835]
        LD    (HL),A                 ;                              [36836]
        LD    DE,31                  ;                              [36837]
        ADD   HL,DE                  ;                              [36840]
        LD    (HL),A                 ;                              [36841]
        INC   HL                     ;                              [36842]
        LD    (HL),A                 ;                              [36843]
        LD    DE,PORTALG             ; Point DE at the graphic data for the portal at      [36844]
                                     ;   PORTALG
        LD    HL,(PORTALLOC2)        ; Pick up the address of the portal's location in the      [36847]
                                     ;   screen buffer at 24576 from PORTALLOC2
        LD    C,0                    ; C=0: overwrite mode      [36850]
; --------------------------------------------------------------------
; Draw a sprite
;
; Used by the routines at START (to draw Willy on the title screen), LOOP
; (to draw the remaining lives), ENDGAM (to draw Willy, the boot and the
; plinth during the game over sequence), DRAWHG (to draw horizontal
; guardians), EUGENE (to draw Eugene in CAVERN4(Eugene's Lair)), SKYLABS (to
; draw the Skylabs in CAVERN13(Skylab Landing Bay)), VGUARDIANS (to draw vertical
; guardians), CHKPORTAL (to draw the portal in the current cavern), NXSHEET (to
; draw Willy above ground and the swordfish graphic over the portal in
; CAVERN19(The Final Barrier)) and KONGBEAST (to draw the Kong Beast in
; CAVERN7(Miner Willy meets the Kong Beast) and CAVERN11(Return of the Alien
; Kong Beast)). If C=1 on entry, this routine returns with the zero flag
; reset if any of the set bits in the sprite being drawn collides with a set
; bit in the background.
;
; C Drawing mode: 0 (overwrite) or 1 (blend)
; DE Address of sprite graphic data
; HL Address to draw at
; --------------------------------------------------------------------
DRWFIX:
        LD    B,16                   ; There are 16 rows of pixels to draw      [36852]
        BIT   0,C                    ; Set the zero flag if we're in overwrite mode      [36854]
        LD    A,(DE)                 ; Pick up a sprite graphic byte      [36856]
        JR    Z,36863                ; Jump if we're in overwrite mode      [36857]
        AND   (HL)                   ; Return with the zero flag reset if any of the set bits      [36859]
        RET   NZ                     ; in the sprite graphic byte collide with a set bit in the      [36860]
                                     ;   background (e.g. in Willy's sprite)
        LD    A,(DE)                 ; Pick up the sprite graphic byte again      [36861]
        OR    (HL)                   ; Blend it with the background byte      [36862]
        LD    (HL),A                 ; Copy the graphic byte to its destination cell      [36863]
        INC   L                      ; Move HL along to the next cell on the right      [36864]
        INC   DE                     ; Point DE at the next sprite graphic byte      [36865]
        BIT   0,C                    ; Set the zero flag if we're in overwrite mode      [36866]
        LD    A,(DE)                 ; Pick up a sprite graphic byte      [36868]
        JR    Z,36875                ; Jump if we're in overwrite mode      [36869]
        AND   (HL)                   ; Return with the zero flag reset if any of the set bits      [36871]
        RET   NZ                     ; in the sprite graphic byte collide with a set bit in the      [36872]
                                     ;   background (e.g. in Willy's sprite)
        LD    A,(DE)                 ; Pick up the sprite graphic byte again      [36873]
        OR    (HL)                   ; Blend it with the background byte      [36874]
        LD    (HL),A                 ; Copy the graphic byte to its destination cell      [36875]
        DEC   L                      ; Move HL to the next pixel row down in the cell on      [36876]
        INC   H                      ; the left      [36877]
        INC   DE                     ; Point DE at the next sprite graphic byte      [36878]
        LD    A,H                    ; Have we drawn the bottom pixel row in this pair of      [36879]
        AND   7                      ; cells yet?      [36880]
        JR    NZ,36900               ; Jump if not      [36882]
        LD    A,H                    ; Otherwise move HL to the top pixel row in the cell      [36884]
        SUB   8                      ; below      [36885]
        LD    H,A                    ;                              [36887]
        LD    A,L                    ;                              [36888]
        ADD   A,32                   ;                              [36889]
        LD    L,A                    ;                              [36891]
        AND   224                    ; Was the last pair of cells at y-coordinate 7 or 15?      [36892]
        JR    NZ,36900               ; Jump if not      [36894]
        LD    A,H                    ; Otherwise adjust HL to account for the movement      [36896]
        ADD   A,8                    ; from the top or middle third of the screen to the next      [36897]
        LD    H,A                    ; one down      [36899]
        DJNZ  36854                  ; Jump back until all 16 rows of pixels have been drawn      [36900]
        XOR   A                      ; Set the zero flag (to indicate no collision)      [36902]
        RET                          ;                              [36903]
; --------------------------------------------------------------------
; Move to the next cavern
;
; Used by the routines at LOOP and CHKPORTAL.
; --------------------------------------------------------------------
NXSHEET:
        LD    A,(SHEET)              ; Pick up the number of the current cavern from SHEET      [36904]
        INC   A                      ; Increment the cavern number      [36907]
        CP    20                     ; Is the current cavern CAVERN19(The Final Barrier)?      [36908]
        JR    NZ,37009               ; Jump if not      [36910]
        LD    A,(DEMO)               ; Pick up the game mode indicator from DEMO      [36912]
        OR    A                      ; Are we in demo mode?      [36915]
        JP    NZ,37008               ; Jump if so      [36916]
        LD    A,(CHEAT)              ; Pick up the 6031769 key counter from CHEAT      [36919]
        CP    7                      ; Is cheat mode activated?      [36922]
        JR    Z,37008                ; Jump if so      [36924]
; --------------------------------------------------------------------
; Willy has made it through CAVERN19(The Final Barrier) without cheating.
; --------------------------------------------------------------------
        LD    C,0                    ; Draw Willy at (2,19) on the ground above the portal      [36926]
        LD    DE,WILLYR3             ;                              [36928]
        LD    HL,16467               ;                              [36931]
        CALL  DRWFIX                 ;                              [36934]
        LD    DE,SWORDFISH           ; Draw the swordfish graphic (see SWORDFISH) over the      [36937]
        LD    HL,16563               ; portal      [36940]
        CALL  DRWFIX                 ;                              [36943]
        LD    HL,22611               ; Point HL at (2,19) in the attribute file      [36946]
        LD    DE,31                  ; Prepare DE for addition      [36949]
        LD    (HL),47                ; Set the attributes for the upper half of Willy's sprite      [36952]
        INC   HL                     ; at (2,19) and (2,20) to #b47 (INK 7: PAPER 5)      [36954]
        LD    (HL),47                ;                              [36955]
        ADD   HL,DE                  ; Set the attributes for the lower half of Willy's sprite      [36957]
        LD    (HL),39                ; at (3,19) and (3,20) to #b39 (INK 7: PAPER 4)      [36958]
        INC   HL                     ;                              [36960]
        LD    (HL),39                ;                              [36961]
        ADD   HL,DE                  ; Point HL at (5,19) in the attribute file      [36963]
        INC   HL                     ;                              [36964]
        ADD   HL,DE                  ;                              [36965]
        LD    (HL),69                ; Set the attributes for the fish at (5,19) and (5,20) to      [36966]
        INC   HL                     ; #b69 (INK 5: PAPER 0: BRIGHT 1)      [36968]
        LD    (HL),69                ;                              [36969]
        ADD   HL,DE                  ; Set the attribute for the handle of the sword at (6,19)      [36971]
        LD    (HL),70                ; to #b70 (INK 6: PAPER 0: BRIGHT 1)      [36972]
        INC   HL                     ; Set the attribute for the blade of the sword at (6,20)      [36974]
        LD    (HL),71                ; to #b71 (INK 7: PAPER 0: BRIGHT 1)      [36975]
        ADD   HL,DE                  ; Set the attributes at (7,19) and (7,20) to #b0 (to hide      [36977]
        LD    (HL),0                 ; Willy's feet just below where the portal was)      [36978]
        INC   HL                     ;                              [36980]
        LD    (HL),0                 ;                              [36981]
; --------------------------------------------------------------------
; Now play a celebratory sound effect.
; .
; 1,36983,37008(escape.wav)
; --------------------------------------------------------------------
        LD    BC,0                   ; Prepare C and D for the celebratory sound      [36983]
        LD    D,50                   ; effect      [36986]
        XOR   A                      ; A=0 (black border)      [36988]
        OUT   (254),A                ; Produce the celebratory sound effect: Willy has escaped      [36989]
        XOR   24                     ; from the mine      [36991]
        LD    E,A                    ;                              [36993]
        LD    A,C                    ;                              [36994]
        ADD   A,D                    ;                              [36995]
        ADD   A,D                    ;                              [36996]
        ADD   A,D                    ;                              [36997]
        LD    B,A                    ;                              [36998]
        LD    A,E                    ;                              [36999]
        DJNZ  37000                  ;                              [37000]
        DEC   C                      ;                              [37002]
        JR    NZ,36989               ;                              [37003]
        DEC   D                      ;                              [37005]
        JR    NZ,36989               ;                              [37006]
        XOR   A                      ; A=#b0 (the next cavern will be CAVERN0(Central      [37008]
                                     ;   Cavern))
        LD    (SHEET),A              ; Update the cavern number at SHEET      [37009]
; --------------------------------------------------------------------
; The next section of code cycles the INK and PAPER colours of the current
; cavern.
; --------------------------------------------------------------------
        LD    A,63                   ; Initialise A to #b63 (INK 7: PAPER 7)      [37012]
        LD    HL,22528               ; Set the attributes for the top two-thirds of the screen      [37014]
        LD    DE,22529               ; to the value in A      [37017]
        LD    BC,511                 ;                              [37020]
        LD    (HL),A                 ;                              [37023]
        LDIR                         ;                              [37024]
        LD    BC,4                   ; Pause for about 0.004s      [37026]
        DJNZ  37029                  ;                              [37029]
        DEC   C                      ;                              [37031]
        JR    NZ,37029               ;                              [37032]
        DEC   A                      ; Decrement the attribute value in A      [37034]
        JR    NZ,37014               ; Jump back until we've gone through all attribute values      [37035]
                                     ;   from #b63 down to #b1
        LD    A,(DEMO)               ; Pick up the game mode indicator from DEMO      [37037]
        OR    A                      ; Are we in demo mode?      [37040]
        JP    NZ,NEWSHT              ; If so, demo the next cavern      [37041]
; --------------------------------------------------------------------
