; --------------------------------------------------------------------
; Print a message
;
; Used by the routines at START, STARTGAME, LOOP, ENDGAM and NXSHEET.
;
; IX Address of the message
; C Length of the message
; DE Display file address
; --------------------------------------------------------------------
PMESS:
        LD    A,(IX+0)               ; Collect a character from the message      [37562]
        CALL  PRINTCHAR              ; Print it      [37565]
        INC   IX                     ; Point IX at the next character in the message      [37568]
        INC   E                      ; Point DE at the next character cell (subtracting 8      [37570]
        LD    A,D                    ; from D compensates for the operations performed by      [37571]
        SUB   8                      ; the routine at PRINTCHAR)      [37572]
        LD    D,A                    ;                              [37574]
        DEC   C                      ; Have we printed the entire message yet?      [37575]
        JR    NZ,PMESS               ; If not, jump back to print the next character      [37576]
        RET                          ;                              [37578]
; --------------------------------------------------------------------
; Print a single character
;
; Used by the routine at PMESS.
;
; A ASCII code of the character
; DE Display file address
; --------------------------------------------------------------------
PRINTCHAR:
        LD    H,7                    ; Point HL at the bitmap for the character (in the      [37579]
        LD    L,A                    ; ROM)      [37581]
        SET   7,L                    ;                              [37582]
        ADD   HL,HL                  ;                              [37584]
        ADD   HL,HL                  ;                              [37585]
        ADD   HL,HL                  ;                              [37586]
        LD    B,8                    ; There are eight pixel rows in a character bitmap      [37587]
; --------------------------------------------------------------------
; This entry point is used by the routine at DRAWITEMS to draw an item in the
; current cavern.
; --------------------------------------------------------------------
        LD    A,(HL)                 ; Copy the character bitmap to the screen (or item      [37589]
        LD    (DE),A                 ; graphic to the screen buffer)      [37590]
        INC   HL                     ;                              [37591]
        INC   D                      ;                              [37592]
        DJNZ  37589                  ;                              [37593]
        RET                          ;                              [37595]
; --------------------------------------------------------------------
; Play the theme tune (The Blue Danube)
;
; Used by the routine at START. Returns with the zero flag reset if ENTER or
; the fire button is pressed while the tune is being played.
;
; IY THEMETUNE (tune data)
; --------------------------------------------------------------------
PLAYTUNE:
        LD    A,(IY+0)               ; Pick up the next byte of tune data from the table at      [37596]
                                     ;   THEMETUNE
        CP    255                    ; Has the tune finished?      [37599]
