        LD    C,A                    ; Copy the first byte of data for this note (which      [37602]
                                     ;   determines the duration) to C
        LD    B,0                    ; Initialise B, which will be used as a delay counter      [37603]
                                     ;   in the note-producing loop
        XOR   A                      ; Set A=0 (for no apparent reasaon)      [37605]
        LD    D,(IY+1)               ; Pick up the second byte of data for this note      [37606]
        LD    A,D                    ; Copy it to A      [37609]
        CALL  PIANOKEY               ; Calculate the attribute file address for the      [37610]
                                     ;   corresponding piano key
